mapper.sql:
SELECT , m.genre AS movie_genre, m.rating AS movie_rating

WHERE s.deleted = 0 AND m.deleted = 0 AND c.deleted = 0 AND h.deleted = 0
  AND s.status = 0 AND m.status = 1 AND c.status = 1 AND h.status = 1
  AND s.available_seats > 0
  AND s.start_time >= #{bookableAfter}
  AND s.start_time >= #{startTime} AND s.start_time < #{endTime}
AND s.movie_id = #{movieId}
AND s.cinema_id = #{cinemaId}

    AND LOCATE(#{filters.genre}, m.genre) > 0
    AND m.rating >= #{filters.minRating}
    AND m.duration <= #{filters.maxDuration}
    AND LOCATE(LOWER(#{filters.hallKeyword}), LOWER(h.name)) > 0

        AND (LOCATE(#{filters.cinemaKeyword}, c.name) > 0 OR LOCATE(#{filters.cinemaKeyword}, c.address) > 0)

    AND s.available_seats >= #{filters.people}
    AND s.id = #{filters.showtimeId}
    AND s.end_time <= #{filters.endBefore}


            AND LOCATE(#{excludedGenre}, COALESCE(m.genre, '')) = 0



        AND s.movie_id NOT IN #{excludedId}




        AND s.base_price < #{maxPrice}
        AND s.base_price <= #{maxPrice}


ORDER BY s.base_price ASC, s.start_time ASC, s.id ASC

